package zkcircuit

import (
	"strings"
	"testing"
)

// Temporary reproduction for the compiled_haſh lookalike bypass.
func TestReproLookalikeBypass(t *testing.T) {
	dir, h := seedBoundJobStore(t)
	valid, err := readDataFile(t, dir)
	if err != nil {
		t.Fatal(err)
	}
	field := `"compiled_hash": "` + h + `"`
	// long s (U+017F) instead of ASCII s, value null
	bad := strings.Replace(string(valid), field, `"compiled_haſh": null`, 1)
	writeDataFile(t, dir, []byte(bad))

	s, err := Open(dir)
	if err != nil {
		t.Logf("open refused (fixed behavior): %v", err)
		return
	}
	defer s.Close()
	j, err := s.GetJob("j-bound")
	if err != nil {
		t.Logf("GetJob err: %v", err)
		return
	}
	t.Logf("BUG PRESENT: damaged binding read as job: %+v", j)
}

