	cases := []struct {
		name   string
		member func(h string) string
	}{
		{"long s null", func(string) string { return `"compiled_ha` + longS + `h": null` }},
		{"escaped long s null", func(string) string { return `"compiled_haſh": null` }},
		{"long s legal hash", func(h string) string { return `"compiled_ha` + longS + `h": "` + h + `"` }},
		{"escaped long s legal hash", func(h string) string { return `"compiled_haſh": "` + h + `"` }},
		{"long s empty string", func(string) string { return `"compiled_ha` + longS + `h": ""` }},
		{"escaped long s empty string", func(string) string { return `"compiled_haſh": ""` }},
		// Kelvin sign (U+212A) folds onto ASCII 'k'; the field has no k, so
		// use it inside a lookalike of a key that does — the rule is about
		// any Unicode fold, so prove it on another folded rune as well by
		// targeting the prefix length boundary through uppercase K: the
		// binding field itself has no k, hence this case documents that an
		// unrelated Unicode key is simply an unknown member and stays legal.
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			dir, hash := seedBoundJobStore(t)
			bad := rewriteBoundHashLookalike(t, dir, hash, tc.member(hash))

