		{"lookalike then standard, equal hashes", lookalike(hashV) + ", " + standard(hashV)},
		{"standard then lookalike, differing values", standard(hashV) + ", " + lookalike(otherV)},
		{"lookalike then standard, differing values", lookalike(otherV) + ", " + standard(hashV)},
