				t.Fatalf("error does not name the damaged job and binding field: %v", err)
			}
			got, rerr := readDataFile(t, dir)
			if rerr != nil {
				t.Fatal(rerr)
			}
			if string(got) != bad {
				t.Fatalf("open modified the damaged file")
