package main

import (
	"fmt"
	"strings"
)

func main() {
	target := "compiled_hash"
	for _, k := range []string{
		"compiled_haſh", // long s for s
		"compİled_hash", // İ for i
		"complıed_hash", // ı dotless i
		"compiled_haſ",  // no trailing h: different rune count
		"COMPILED_HASH",
	} {
		fmt.Printf("%-20q EqualFold=%v asciiVariant=%v\n", k,
			strings.EqualFold(k, target), asciiOnly(k, target))
	}
}

func asciiOnly(k, target string) bool {
	if len(k) != len(target) { return false }
	for i := 0; i < len(k); i++ {
		c := k[i]
		if c >= 'A' && c <= 'Z' { c += 'a' - 'A' }
		if c != target[i] { return false }
	}
	return true
}
